1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = {
41	  premium: number;
42	};
43	
44	export type ClaimResult = {
45	  payout: number;
46	  remainingCap: number;
47	};
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export type ScenarioResult = {
52	  results: StepResult[];
53	};
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	// The MHPCO's price list. One row per insurable item type: what it costs to
59	// insure, and what it is insured for. Keeping both figures in a single table
60	// makes "insurable type" one fact rather than two lists that must agree.
61	const PRICE_LIST: Record<string, { basePremium: number; insuranceValue: number }> = {
62	  sword: { basePremium: 100, insuranceValue: 1000 },
63	  amulet: { basePremium: 60, insuranceValue: 600 },
64	  staff: { basePremium: 80, insuranceValue: 800 },
65	  potion: { basePremium: 40, insuranceValue: 400 },
66	  rune: { basePremium: 25, insuranceValue: 250 },
67	  moonstone: { basePremium: 25, insuranceValue: 250 },
68	};
69	
70	const DEDUCTIBLE_PER_DAMAGE = 100;
71	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
72	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
73	const FULL_REIMBURSEMENT_RATE = 1;
74	const CAP_MULTIPLIER = 2;
75	
76	const CURSE_SURCHARGE_RATE = 0.5;
77	const HIGH_ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
78	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
79	const LOYALTY_YEARS_THRESHOLD = 2;
80	const LOYALTY_DISCOUNT_RATE = 0.2;
81	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
82	
83	const BLOCK_SIZE = 3;
84	const BLOCK_BASE_PREMIUM = 60;
85	
86	// The MHPCO insures only what is on its price list. Every figure the office
87	// quotes or pays out is read through here, so an uninsurable type is rejected
88	// at the one point that knows the price list at all.
89	const priceListEntryForType = (
90	  type: string,
91	): { basePremium: number; insuranceValue: number } => {
92	  const entry = PRICE_LIST[type];
93	  if (entry === undefined) {
94	    throw new Error(`the MHPCO does not insure items of type ${type}`);
95	  }
96	
97	  return entry;
98	};
99	
100	const basePremiumForType = (type: string): number =>
101	  priceListEntryForType(type).basePremium;
102	
103	const insuranceValueForType = (type: string): number =>
104	  priceListEntryForType(type).insuranceValue;
105	
106	const countByType = (items: Item[]): Map<string, number> => {
107	  const counts = new Map<string, number>();
108	  for (const item of items) {
109	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
110	  }
111	  return counts;
112	};
113	
114	// A block is exactly BLOCK_SIZE alike items, charged as one unit.
115	const formsBlock = (count: number): boolean => count === BLOCK_SIZE;
116	
117	const groupBasePremium = (type: string, count: number): number =>
118	  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * basePremiumForType(type);
119	
120	const policyBasePremium = (items: Item[]): number =>
121	  [...countByType(items)].reduce(
122	    (total, [type, count]) => total + groupBasePremium(type, count),
123	    0,
124	  );
125	
126	// The MHPCO rounds in its own favour, which cuts in opposite directions for
127	// the two quantities it settles: premiums up, payouts down.
128	const roundPremiumInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
129	const roundPayoutInMHPCOsFavour = (amount: number): number => Math.floor(amount);
130	
131	// Item-scoped surcharge clauses. Each applies, independently and additively,
132	// to the affected item's own base premium.
133	const ITEM_SURCHARGE_CLAUSES: {
134	  applies: (item: Item) => boolean;
135	  rate: number;
136	}[] = [
137	  {
138	    applies: (item) => item.cursed === true,
139	    rate: CURSE_SURCHARGE_RATE,
140	  },
141	  {
142	    applies: (item) =>
143	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_SURCHARGE_THRESHOLD,
144	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
145	  },
146	];
147	
148	const itemSurcharge = (item: Item): number => {
149	  const base = basePremiumForType(item.type);
150	
151	  return ITEM_SURCHARGE_CLAUSES.filter((clause) => clause.applies(item)).reduce(
152	    (total, clause) => total + base * clause.rate,
153	    0,
154	  );
155	};
156	
157	const totalItemSurcharges = (items: Item[]): number =>
158	  items.reduce((total, item) => total + itemSurcharge(item), 0);
159	
160	// Everything a policy-scoped clause may inspect.
161	type Policy = {
162	  items: Item[];
163	  customer: Customer;
164	  isFollowUpContract: boolean;
165	};
166	
167	// Policy-scoped modifier clauses. Each applies, independently and additively,
168	// to the policy base premium. A negative rate is a discount.
169	const POLICY_MODIFIER_CLAUSES: {
170	  applies: (policy: Policy) => boolean;
171	  rate: number;
172	}[] = [
173	  {
174	    applies: () => true,
175	    rate: FIRST_INSURANCE_SURCHARGE_RATE,
176	  },
177	  {
178	    applies: (policy) =>
179	      policy.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
180	    rate: -LOYALTY_DISCOUNT_RATE,
181	  },
182	  {
183	    applies: (policy) => policy.isFollowUpContract,
184	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
185	  },
186	];
187	
188	const policyModifierAmount = (policy: Policy, policyBase: number): number =>
189	  POLICY_MODIFIER_CLAUSES.filter((clause) => clause.applies(policy)).reduce(
190	    (total, clause) => total + policyBase * clause.rate,
191	    0,
192	  );
193	
194	// A premium is the policy's base, plus the surcharges its individual items
195	// attract, plus the policy-wide modifiers, plus the flat fee — all kept as
196	// exact fractions so that only the final figure is rounded.
197	const quote = (policy: Policy): QuoteResult => {
198	  const policyBase = policyBasePremium(policy.items);
199	  const premiumBeforeRounding =
200	    policyBase +
201	    totalItemSurcharges(policy.items) +
202	    policyModifierAmount(policy, policyBase) +
203	    PROCESSING_FEE;
204	
205	  return { premium: roundPremiumInMHPCOsFavour(premiumBeforeRounding) };
206	};
207	
208	const insuranceSum = (items: Item[]): number =>
209	  items.reduce((total, item) => total + insuranceValueForType(item.type), 0);
210	
211	// A policy issued by a quote step, tracked so later claims can draw on its cap.
212	type IssuedPolicy = {
213	  items: Item[];
214	  remainingCap: number;
215	};
216	
217	// The cap a fresh policy starts with: a multiple of the insured items' value,
218	// independent of any premium modifiers.
219	const issuePolicy = (items: Item[]): IssuedPolicy => ({
220	  items,
221	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
222	});
223	
224	// Item-scoped reimbursement clauses. Unlike the additive premium surcharges,
225	// these compete: the first applicable clause sets the rate outright, so list
226	// order is precedence. An item no clause applies to is reimbursed in full.
227	//
228	// The spec's dragon-material clause ("fully reimbursed") is deliberately not
229	// listed. Full reimbursement is already the default, and where it would
230	// collide with the high-enchantment clause the spec says the 50 % rule wins —
231	// which is what precedence gives. A dragon row would therefore be
232	// unreachable: no input distinguishes its presence from its absence.
233	const ITEM_REIMBURSEMENT_CLAUSES: {
234	  applies: (item: Item) => boolean;
235	  rate: number;
236	}[] = [
237	  {
238	    applies: (item) =>
239	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD,
240	    rate: HIGH_ENCHANTMENT_REIMBURSEMENT_RATE,
241	  },
242	];
243	
244	const reimbursementRate = (item: Item): number =>
245	  ITEM_REIMBURSEMENT_CLAUSES.find((clause) => clause.applies(item))?.rate ??
246	  FULL_REIMBURSEMENT_RATE;
247	
248	// Reimbursement clauses read the damaged item, so a claim resolves each
249	// damage entry back to the insured item it refers to.
250	const reimbursedAmount = (item: Item, amount: number): number =>
251	  amount * reimbursementRate(item);
252	
253	// A damage entry resolved to the one insured item it is settled against.
254	type DamagedItem = {
255	  item: Item;
256	  amount: number;
257	};
258	
259	// Each damage entry is settled against a *distinct* insured item, so a claim
260	// cannot draw on the same item twice. Pairing every entry up front — rather
261	// than resolving items one at a time while totalling — keeps the "each item is
262	// claimed at most once" rule in a single place, and leaves the payout
263	// arithmetic below free of the bookkeeping.
264	// The office settles losses, not gains: a negative damage would pay the MHPCO.
265	const rejectNegativeDamage = (damage: Damage): void => {
266	  if (damage.amount < 0) {
267	    throw new Error(
268	      `a damage amount cannot be negative, but ${damage.itemType} reports ${damage.amount}`,
269	    );
270	  }
271	};
272	
273	// Removes and returns the first unclaimed item of the damaged type, so that
274	// each insured item can back at most one damage entry.
275	const takeInsuredItem = (unclaimed: Item[], itemType: string): Item => {
276	  const index = unclaimed.findIndex((item) => item.type === itemType);
277	  if (index === -1) {
278	    throw new Error(
279	      `the policy does not cover a further ${itemType} to claim against`,
280	    );
281	  }
282	
283	  return unclaimed.splice(index, 1)[0];
284	};
285	
286	const pairDamagesWithInsuredItems = (
287	  damages: Damage[],
288	  items: Item[],
289	): DamagedItem[] => {
290	  const unclaimed = [...items];
291	
292	  return damages.map((damage) => {
293	    rejectNegativeDamage(damage);
294	
295	    return {
296	      item: takeInsuredItem(unclaimed, damage.itemType),
297	      amount: damage.amount,
298	    };
299	  });
300	};
301	
302	// Each damaged item carries its own deductible, and a damage smaller than the
303	// deductible contributes nothing rather than clawing money back off the claim.
304	const payoutFor = ({ item, amount }: DamagedItem): number =>
305	  Math.max(0, reimbursedAmount(item, amount) - DEDUCTIBLE_PER_DAMAGE);
306	
307	// What the incident claims, before the policy's cap is applied.
308	const claimedAmount = (incident: Incident, items: Item[]): number =>
309	  pairDamagesWithInsuredItems(incident.damages, items).reduce(
310	    (total, damaged) => total + payoutFor(damaged),
311	    0,
312	  );
313	
314	// A claim draws its payout down from the policy's remaining cap, so the
315	// policy carries less cover into any later claim against it.
316	const drawDownCap = (policy: IssuedPolicy, payout: number): IssuedPolicy => ({
317	  ...policy,
318	  remainingCap: policy.remainingCap - payout,
319	});
320	
321	// A policy never pays out more cover than it has left.
322	const cappedBy = (amount: number, remainingCap: number): number =>
323	  Math.min(amount, remainingCap);
324	
325	// Settling a claim pays out what the incident claims, capped by the cover the
326	// policy has left and rounded down. Only this final figure is rounded, so the
327	// cap draws down by the amount actually paid. Returns the payout alongside the
328	// drawn-down policy, leaving it to the caller to record.
329	const settleClaim = (
330	  incident: Incident,
331	  policy: IssuedPolicy,
332	): { result: ClaimResult; policy: IssuedPolicy } => {
333	  const claimed = claimedAmount(incident, policy.items);
334	  const covered = cappedBy(claimed, policy.remainingCap);
335	  const payout = roundPayoutInMHPCOsFavour(covered);
336	  const settled = drawDownCap(policy, payout);
337	
338	  return {
339	    result: { payout, remainingCap: settled.remainingCap },
340	    policy: settled,
341	  };
342	};
343	
344	// A claim names the quote step whose policy it draws on, so that step must
345	// already have issued one.
346	const policyIssuedBy = (
347	  policies: Map<number, IssuedPolicy>,
348	  step: number,
349	): IssuedPolicy => {
350	  const policy = policies.get(step);
351	  if (policy === undefined) {
352	    throw new Error(`no policy was issued by step ${step} to claim against`);
353	  }
354	
355	  return policy;
356	};
357	
358	export const runScenario = (scenario: Scenario): ScenarioResult => {
359	  let hasIssuedContract = false;
360	  const policies = new Map<number, IssuedPolicy>();
361	
362	  const results = scenario.steps.map((step, index): StepResult => {
363	    if (step.op === "claim") {
364	      const { result, policy } = settleClaim(
365	        step.incident,
366	        policyIssuedBy(policies, step.policy),
367	      );
368	      policies.set(step.policy, policy);
369	
370	      return result;
371	    }
372	
373	    policies.set(index, issuePolicy(step.items));
374	
375	    const result = quote({
376	      items: step.items,
377	      customer: scenario.customer,
378	      isFollowUpContract: hasIssuedContract,
379	    });
380	    hasIssuedContract = true;
381	
382	    return result;
383	  });
384	
385	  return { results };
386	};
