export const runScenario = (scenario: Scenario): ScenarioResult => {
  let hasIssuedContract = false;
  const policies = new Map<number, IssuedPolicy>();

  const results = scenario.steps.map((step, index): StepResult => {
    if (step.op === "claim") {
      const { result, policy } = settleClaim(
        step.incident,
        policyIssuedBy(policies, step.policy),
      );
      policies.set(step.policy, policy);

      return result;
    }

    policies.set(index, issuePolicy(step.items));

    const result = quote({
      items: step.items,
      customer: scenario.customer,
      isFollowUpContract: hasIssuedContract,
    });
    hasIssuedContract = true;

    return result;
  });

  return { results };
};

